const D = { density:.55, energy:.6, hue:175, speed:1, scale:1, x:.5, y:.5, wake:.6, current:.6, style:'sea_sparkle', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u=Math.min(width,height);
if(!S.spr){ const R=40; const s=createGraphics(R*2,R*2); s.pixelDensity(1); s.noStroke();
  for(let r=R;r>0;r--){ const a=Math.pow(1-r/R,1.9)*255; s.fill(255,255,255,a); s.ellipse(R,R,r*2,r*2); }
  S.spr=s; }
// dim current wash buffer (broad area element)
const BW=Math.max(400,Math.min(680,Math.round(width/2.7))), BH=Math.max(140,Math.round(BW*height/width));
if(!S.g||S.bw!==BW||S.bh!==BH){ S.g=createGraphics(BW,BH); S.g.pixelDensity(1); S.bw=BW; S.bh=BH; }
if(S.seedUsed!==P.seed){ S.seedUsed=P.seed;
  const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s);};
  S.hoff=fr(1); S.pk=[]; for(let k=0;k<420;k++) S.pk.push([fr(k*3+2),fr(k*3+3),fr(k*3+4)]);
}
const sd=P.seed|0;
function hsh(ix,iy){ let h=(ix*374761393+iy*668265263+sd*2147483647)|0; h=(h^(h>>>13))*1274126177|0; return ((h^(h>>>16))>>>0)/4294967295; }
function vn(x,y){ const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy,uu=fx*fx*(3-2*fx),vv=fy*fy*(3-2*fy); const a=hsh(ix,iy),b=hsh(ix+1,iy),c=hsh(ix,iy+1),d=hsh(ix+1,iy+1); return a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv; }
function fbm(x,y){ return 0.6*vn(x,y)+0.3*vn(x*2.03+5.1,y*2.03-3.2)+0.15*vn(x*4.1-2.3,y*4.1+7.7); }

const t=K.t;
const style=P.style;
const col = style==='noctiluca'?[0.2,0.5,1.0] : style==='firefly_squid'?[0.1,0.4,1.0] : style==='ghost'?[0.7,1.0,0.85] : [0.2,1.0,0.7];
// wake path: a swept disturbance line crossing the frame on incommensurate rates
const wx=(0.5+0.42*Math.sin(t*0.37)+0.12*Math.sin(t*0.91+1.1))*width;
const wy=(0.5+0.34*Math.sin(t*0.53+2.0)+0.10*Math.sin(t*1.19))*height;
const wr=u*(0.16+P.wake*0.24);

// --- current wash ---
const cst=(0.06+P.current*0.28);
const gg=S.g; gg.loadPixels(); const px=gg.pixels;
for(let j=0;j<BH;j++){ const yy=j/BH;
  for(let i=0;i<BW;i++){ const xx=i/BW;
    const f=fbm(xx*2.4 + t*0.04, yy*2.0 - t*0.06 + S.hoff*5);
    const shear=0.5+0.5*Math.sin(yy*7+ t*0.3 + f*3);
    let L=(0.3+0.8*f)*shear*cst;
    const o=4*(j*BW+i); px[o]=Math.min(255,col[0]*L*255); px[o+1]=Math.min(255,col[1]*L*255); px[o+2]=Math.min(255,col[2]*L*255); px[o+3]=255;
  }}
gg.updatePixels();
push(); blendMode(ADD); if(P.alpha<100) tint(0,0,100,P.alpha); image(gg,0,0,width,height); blendMode(BLEND); pop();

// --- plankton flashes ---
const np=Math.round(120+P.density*280);
const hb=(P.hue+K.section*3)%360;
push(); blendMode(ADD); imageMode(CENTER); noStroke();
for(let k=0;k<np;k++){ const pk=S.pk[k];
  // slow lateral advection by current so the field is never frozen
  let x=(pk[0] + 0.03*Math.sin(t*0.2+pk[1]*6.28) + t*0.004*(0.4+pk[2]))%1; if(x<0)x+=1;
  let y=(pk[1] + 0.02*Math.cos(t*0.17+pk[0]*6.28))%1; if(y<0)y+=1;
  const X=x*width, Y=y*height;
  const dwx=X-wx, dwy=Y-wy, dw=Math.sqrt(dwx*dwx+dwy*dwy);
  // ignite strongly near the wake, plus a baseline sparkle on own phase
  const near=Math.max(0, 1-dw/wr);
  const ignite=Math.pow(near,1.5)*(0.7+P.wake*0.8);
  const own=Math.max(0, Math.sin(t*(1.5+pk[2]*3) + pk[0]*30))-0.7;
  let flash=(ignite*1.2 + own*3.0*(0.3+pk[2]))*(0.5+P.energy*0.9);
  flash+= A.treble*near*0.8;
  if(flash>0.03){
    const sz=u*(0.004+pk[2]*0.012)*P.scale;
    tint(hb, 55, 100, Math.min(100, 22*flash)); image(S.spr,X,Y,sz*3.0,sz*3.0);
    tint(hb, 30, 100, Math.min(100, 85*flash)); image(S.spr,X,Y,sz,sz);
  }
}
imageMode(CORNER); blendMode(BLEND); pop();
